using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

// --- Part 1: GetTypeInfo<T>() with reflection-based resolver ---
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

// Returns a strongly-typed JsonTypeInfo<Person> — no cast required.
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"[GetTypeInfo<Person>] Type = {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 42), personInfo);
Console.WriteLine($"  Serialized: {json}");

// --- Part 2: TryGetTypeInfo<T>() — check without throwing ---

// With the full reflection resolver, Person resolves fine:
if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
    Console.WriteLine($"[TryGetTypeInfo<Person>] Resolved: {info!.Type.Name}");

// Now use a restricted resolver that only knows about Person.
var restricted = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
        .WithAddedModifier(ti =>
        {
            // Reject everything except Person
            if (ti.Type != typeof(Person))
                throw new NotSupportedException();
        })
};

// Probe for int[] — resolver won't provide it, so TryGetTypeInfo returns false.
if (restricted.TryGetTypeInfo<int[]>(out JsonTypeInfo<int[]>? arrayInfo))
{
    Console.WriteLine($"[TryGetTypeInfo<int[]>] Unexpected success");
}
else
{
    Console.WriteLine("[TryGetTypeInfo<int[]>] Not available — no exception thrown");
}

public record Person(string Name, int Age);
EOF

